scripts_as_text.latin_corpus.py:
"""Surface-token and document input for the Latin LLCT context experiment.

The UD r2.18 LLCT split files identify each charter in the sentence's
``# reference = document_id='…'-span='…'`` comment. The complete quoted
identifier is interpreted consistently across split files, and the span is a separate
within-document locator. A ``# newdoc id`` can also identify documents in
other CoNLL-U sources. Sentence order and all source split labels stay intact.
"""

from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
import re
import unicodedata


_SPECIAL = {
    "ß": "ss", "æ": "ae", "œ": "oe", "þ": "th", "ð": "d",
    "ȝ": "y", "ſ": "s", "ø": "o", "ł": "l",
}
_NON_ASCII_LETTERS = re.compile(r"[^a-z]+")
_NEW_DOC = re.compile(r"^#\s*newdoc(?:\s+id\s*=\s*(\S.*))?\s*$")
_REFERENCE = re.compile(r"^#\s*reference\s*=")
_REFERENCE_DOC = re.compile(r"\bdocument_id\s*=\s*(['\"])(.*?)\1")
_REFERENCE_SPAN = re.compile(r"\bspan\s*=\s*(['\"])(.*?)\1")
_SENT_ID = re.compile(r"^#\s*sent_id\s*=\s*(\S+)\s*$")
_TEXT = re.compile(r"^#\s*text\s*=\s*(.*)$")
_WORD_ID = re.compile(r"[1-9][0-9]*\Z")
_RANGE_ID = re.compile(r"([1-9][0-9]*)-([1-9][0-9]*)\Z")
_EMPTY_ID = re.compile(r"[0-9]+\.[1-9][0-9]*\Z")


@dataclass(frozen=True, slots=True)
class Morphology:
    lemma: str | None
    lemma_ascii: str | None
    upos: str | None
    case: str | None
    number: str | None
    gender: str | None


@dataclass(frozen=True, slots=True)
class SyntacticWord:
    index: int
    form: str
    morphology: Morphology


@dataclass(frozen=True, slots=True)
class SurfaceToken:
    id: str
    form: str
    ascii_parts: tuple[str, ...]
    words: tuple[SyntacticWord, ...]
    space_after: bool

    @property
    def morphology(self) -> Morphology | None:
        """Single-word analysis only; a multiword token has several analyses."""
        if len(self.words) != 1 or len(self.ascii_parts) != 1:
            return None
        return self.words[0].morphology


@dataclass(frozen=True, slots=True)
class Sentence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    text: str | None
    tokens: tuple[SurfaceToken, ...]


@dataclass(frozen=True, slots=True)
class Occurrence:
    split: str
    doc_id: str | None
    span: str | None
    sent_id: str
    token_id: str
    word: str
    part_index: int
    pair: str
    start: int
    left: str
    right: str
    role: str
    morphology: Morphology | None
    terminal_morphology: Morphology | None

    @property
    def word_initial(self) -> bool:
        return self.role in ("initial", "whole_word")

    @property
    def word_final(self) -> bool:
        return self.role in ("terminal", "whole_word")


def normalize_latin(text: str) -> str:
    """Use the pinned #623 Latin normalization, including j→i and v→u."""
    lowered = text.lower()
    for source, replacement in _SPECIAL.items():
        lowered = lowered.replace(source, replacement)
    unaccented = "".join(c for c in unicodedata.normalize("NFKD", lowered)
                         if not unicodedata.combining(c))
    return _NON_ASCII_LETTERS.sub(" ", unaccented).strip().replace("j", "i").replace("v", "u")


def _maybe(value: str) -> str | None:
    return None if value == "_" else value


def _field_pairs(features: str) -> dict[str, str]:
    if features == "_":
        return {}
    output = {}
    for entry in features.split("|"):
        key, sep, value = entry.partition("=")
        if not sep or not key or not value or key in output:
            raise ValueError(f"invalid or repeated CoNLL-U morphological feature: {entry!r}")
        output[key] = value
    return output


def _word(row: list[str]) -> SyntacticWord:
    lemma = _maybe(row[2])
    feat = _field_pairs(row[5])
    return SyntacticWord(int(row[0]), row[1], Morphology(
        lemma=lemma,
        lemma_ascii=(normalize_latin(lemma) or None) if lemma is not None else None,
        upos=_maybe(row[3]),
        case=feat.get("Case"),
        number=feat.get("Number"),
        gender=feat.get("Gender"),
    ))


def _sentence_blocks(path):
    with Path(path).open(encoding="utf-8-sig") as src:
        comments, rows = [], []
        for line in src:
            line = line.rstrip("\r\n")
            if not line:
                if rows:
                    yield comments, rows
                    comments, rows = [], []
                continue
            if line.startswith("#"):
                if rows:
                    raise ValueError(f"mid-sentence comment in {path}")
                comments.append(line)
            else:
                rows.append(line)
        if rows:
            yield comments, rows


def _identity(comments, active_doc, path):
    sent_id, text, ref_doc, span = None, None, None, None
    for line in comments:
        newdoc = _NEW_DOC.fullmatch(line)
        if newdoc:
            active_doc = newdoc[1].strip() if newdoc[1] is not None else None
        if match := _SENT_ID.fullmatch(line):
            if sent_id is not None:
                raise ValueError(f"repeated sent_id in {path}")
            sent_id = match[1]
        if match := _TEXT.fullmatch(line):
            text = match[1]
        if _REFERENCE.match(line):
            if match := _REFERENCE_DOC.search(line):
                if ref_doc is not None and ref_doc != match[2]:
                    raise ValueError(f"conflicting document_id values in {path}")
                ref_doc = match[2]
            if match := _REFERENCE_SPAN.search(line):
                span = match[2]
    if sent_id is None:
        raise ValueError(f"missing sent_id in {path}")
    if active_doc is not None and ref_doc is not None and active_doc != ref_doc:
        raise ValueError(f"newdoc and reference identify different documents in {path}, {sent_id}")
    return active_doc, ref_doc or active_doc, span, sent_id, text


def _surface_tokens(raw_rows, sent_id):
    word_rows = {}
    surface_rows = []
    covered = set()
    expected = 1
    for line in raw_rows:
        row = line.split("\t")
        if len(row) != 10:
            raise ValueError(f"expected 10 CoNLL-U fields in {sent_id}")
        locator = row[0]
        if _EMPTY_ID.fullmatch(locator):
            continue
        if match := _RANGE_ID.fullmatch(locator):
            start, end = map(int, match.groups())
            if start != expected or end <= start or start in covered:
                raise ValueError(f"misplaced or overlapping multiword token {locator} in {sent_id}")
            covered.update(range(start, end + 1))
            surface_rows.append((row, start, end))
        elif _WORD_ID.fullmatch(locator):
            index = int(locator)
            if index != expected:
                raise ValueError(f"nonconsecutive syntactic word ID {locator} in {sent_id}")
            expected += 1
            word_rows[index] = row
            if index not in covered:
                surface_rows.append((row, index, index))
        else:
            raise ValueError(f"unrecognized CoNLL-U ID {locator!r} in {sent_id}")
    if not covered <= word_rows.keys():
        raise ValueError(f"missing syntactic words for a multiword token in {sent_id}")
    return tuple(SurfaceToken(
        id=row[0], form=row[1], ascii_parts=tuple(normalize_latin(row[1]).split()),
        words=tuple(_word(word_rows[i]) for i in range(start, end + 1)),
        space_after="SpaceAfter=No" not in row[9].split("|"),
    ) for row, start, end in surface_rows)


def iter_sentences(path, *, split: str | None = None):
    """Read sentences and emit each orthographic surface token exactly once."""
    declared_split = Path(path).stem if split is None else split
    active_doc = None
    for comments, raw_rows in _sentence_blocks(path):
        active_doc, doc, span, sent_id, text = _identity(comments, active_doc, path)
        yield Sentence(declared_split, doc, span, sent_id, text, _surface_tokens(raw_rows, sent_id))


def document_membership(paths_by_split, *, require_ids=True):
    """Index raw document IDs by their named source splits, before scoring.

    IDs present in multiple partitions are visible as multiple memberships.
    Do not infer a new identity from the filename, sentence ID, or span.
    """
    membership = defaultdict(set)
    for split, path in paths_by_split.items():
        active_doc = None
        for comments, _ in _sentence_blocks(path):
            active_doc, doc, _, sent_id, _ = _identity(comments, active_doc, path)
            if doc is None:
                if require_ids:
                    raise ValueError(f"missing document identity in {path}, {sent_id}")
                continue
            membership[doc].add(split)
    return {doc: frozenset(splits) for doc, splits in sorted(membership.items())}


def iter_occurrences(sentences, pairs=("us", "um"), *, include_fragments=False):
    """Yield observable contexts without assuming that terminal letters are morphemes.

    Each context uses exactly one intra-word ASCII character per side and a
    virtual space at a word edge, as in #623. Default matching skips tokens
    whose normalization has introduced an internal word break. When enabled
    for a sensitivity, such fragments get character contexts only. A whole
    two-letter word has a role separate from terminal pairs with a stem.
    """
    pairs = frozenset(pairs)
    if any(not isinstance(pair, str) or not re.fullmatch(r"[a-z]{2}", pair) for pair in pairs):
        raise ValueError("pairs must be lowercase ASCII bigrams")
    for sentence in sentences:
        for token in sentence.tokens:
            if len(token.ascii_parts) > 1 and not include_fragments:
                continue
            morphology = token.morphology
            for part_index, word in enumerate(token.ascii_parts):
                for start in range(len(word) - 1):
                    end = start + 2
                    pair = word[start:end]
                    if pair not in pairs:
                        continue
                    if start == 0:
                        role = "whole_word" if end == len(word) else "initial"
                    else:
                        role = "terminal" if end == len(word) else "interior"
                    yield Occurrence(
                        sentence.split, sentence.doc_id, sentence.span, sentence.sent_id,
                        token.id, word, part_index, pair, start,
                        word[start-1] if start else " ", word[end] if end < len(word) else " ",
                        role, morphology, morphology if role == "terminal" else None,
                    )

scripts_as_text.charter_context.py:
"""Apply the published context scores to charter-document controls."""
from collections import Counter, defaultdict
from dataclasses import dataclass
import argparse
import hashlib
import importlib.util
from importlib.machinery import SourceFileLoader
import json
import math
from pathlib import Path
import random

from latin_corpus import iter_sentences


ROOT = Path(__file__).resolve().parent
PLAN_PATH = ROOT / "plan.json"
PLAN = json.loads(PLAN_PATH.read_text())
AMBIENT = ("all", "terminal", "terminal_same_stem_case", "internal",
           "internal_same_morph", "internal_new_lemma", "both_sides_matched")
TOL = 1e-12
prior_loader = SourceFileLoader("prior_position", str(ROOT / "prior-position_context.py"))
prior_spec = importlib.util.spec_from_loader(prior_loader.name, prior_loader)
prior = importlib.util.module_from_spec(prior_spec)
prior_loader.exec_module(prior)
METHODS = tuple(PLAN["methods"])
assert METHODS == prior.METHODS


@dataclass(frozen=True)
class Word:
    index: int
    surface_index: int
    form: str
    lemma: str
    upos: str
    case: str
    number: str
    gender: str


@dataclass(frozen=True)
class Site:
    word: Word
    onset: int
    before: str
    after: str


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_words(split):
    words = []
    chars = Counter()
    surface_no = 0
    path = ROOT / "corpus" / f"{split}.conllu"
    for sentence in iter_sentences(path, split=split):
        chars[sentence.doc_id] += 1
        for token in sentence.tokens:
            surface_no += 1
            morphology = token.morphology
            if morphology is None:
                lemma = upos = case = number = gender = ""
            else:
                lemma = morphology.lemma_ascii or ""
                if " " in lemma:
                    lemma = ""
                upos = morphology.upos or ""
                case = morphology.case or ""
                number = morphology.number or ""
                gender = morphology.gender or ""
            for part in token.ascii_parts:
                words.append(Word(len(words), surface_no, part, lemma, upos, case, number, gender))
    assert chars and words
    return words, {"sha256": sha(path), "documents": sorted(chars), "sentences": sum(chars.values()),
                   "normalized_words": len(words), "surface_tokens_with_punctuation": surface_no}


def all_sites(words, target, decoy):
    sites = []
    for word in words:
        for index in range(len(word.form) - 1):
            pair = word.form[index:index + 2]
            if pair in (target, decoy):
                previous = word.form[index - 1] if index else " "
                following = word.form[index + 2] if index + 2 < len(word.form) else " "
                sites.append((pair == decoy, Site(word, index, previous, following)))
    return sites


def stratum(site, decoy, mode, new_lemmas):
    initial = site.onset == 0
    final = site.after == " "
    basic = (initial, final, site.before)
    word = site.word
    if mode == "all":
        return basic
    if mode == "both_sides_matched":
        return (*basic, site.after)
    if mode == "terminal":
        return basic if final else None
    if mode == "terminal_same_stem_case":
        eligible = (
            final and word.lemma and word.upos in ("NOUN", "ADJ", "PROPN")
            and word.number == "Sing" and word.gender == "Masc"
            and word.case == ("Acc" if decoy else "Nom")
        )
        if eligible:
            return (*basic, word.lemma, word.upos, word.form[:-2])
        return None
    if final:
        return None
    if mode == "internal":
        return basic
    if mode == "internal_same_morph":
        return (*basic, word.upos, word.case, word.number) if word.upos else None
    if mode == "internal_new_lemma":
        return basic if word.lemma in new_lemmas else None
    raise ValueError(mode)


def make_pairs(sites, mode, seed, new_lemmas):
    groups = defaultdict(lambda: ([], []))
    for decoy, site in sites:
        key = stratum(site, decoy, mode, new_lemmas)
        if key is not None:
            groups[key][decoy].append(site)
    counts = [sum(len(pool[side]) for pool in groups.values()) for side in (0, 1)]
    unlimited = sum(min(len(left), len(right)) for left, right in groups.values())
    rng = random.Random(seed)
    matched = []
    used = set()
    group_keys = sorted(groups)
    rng.shuffle(group_keys)
    for key in group_keys:
        left, right = groups[key]
        rng.shuffle(left)
        rng.shuffle(right)
        cursor = 0
        for x in left:
            if x.word.surface_index in used:
                continue
            while cursor < len(right) and right[cursor].word.surface_index in used:
                cursor += 1
            if cursor == len(right):
                break
            choice = cursor
            while choice < len(right) and (
                right[choice].word.surface_index in used
                or right[choice].word.surface_index == x.word.surface_index
            ):
                choice += 1
            if choice == len(right):
                continue
            right[cursor], right[choice] = right[choice], right[cursor]
            z = right[cursor]
            cursor += 1
            used.update((x.word.surface_index, z.word.surface_index))
            matched.append((x, z))
    return matched, {"source_sites": counts, "stratum_unrestricted_upper_bound": unlimited,
                     "shared_nonempty_strata": sum(bool(left and right) for left, right in groups.values())}


def planted_context(words, pairs, target, decoy):
    edited = [word.form for word in words]
    for a, b in pairs:
        assert a.word.form[a.onset:a.onset + 2] == target
        assert b.word.form[b.onset:b.onset + 2] == decoy
        for marker, location in (("X", a), ("Z", b)):
            form = location.word.form
            start = location.onset
            edited[location.word.index] = form[:start] + marker + form[start + 2:]
    return prior.Context(" ".join(edited))


def assess(words, sites, target, decoy, group, seed, new_lemmas):
    pairs, support = make_pairs(sites, group, seed, new_lemmas)
    assert all(a.before == b.before and (a.after == " ") == (b.after == " ") for a, b in pairs)
    outer_match = sum(a.after == b.after for a, b in pairs)
    if group in ("terminal", "terminal_same_stem_case", "both_sides_matched"):
        assert outer_match == len(pairs)
    if len(pairs) < PLAN["candidate_minimum"]:
        values = {marker: dict.fromkeys(METHODS) for marker in ("X", "Z")}
    else:
        context = planted_context(words, pairs, target, decoy)
        assert context.all["X"]["n"] == context.all["Z"]["n"] == len(pairs)
        values = {marker: context.scores(marker, *target) for marker in ("X", "Z")}
        if outer_match == len(pairs):
            assert values["X"] == values["Z"]
    return {
        "target": target, "decoy": decoy, "mode": group, "seed": seed, "pairs": len(pairs),
        "same_right_context": outer_match, "support": support, "scores": values,
        "paired_unique_lemmas": [
            len({pair[side].word.lemma for pair in pairs if pair[side].word.lemma})
            for side in (0, 1)
        ],
        "position_counts": {
            "word_final": sum(a.after == " " for a, _ in pairs),
            "word_initial": sum(a.onset == 0 for a, _ in pairs),
        },
        "case_counts": [
            dict(Counter(pair[side].word.case or "_" for pair in pairs))
            for side in (0, 1)
        ],
    }


def run_rows(words, pairs, modes, new_lemmas):
    output = []
    for target, decoy in pairs:
        sites = all_sites(words, target, decoy)
        for mode in modes:
            for seed in PLAN["seeds"]:
                output.append(assess(words, sites, target, decoy, mode, seed, new_lemmas))
    return output


def common(row):
    return all(row["scores"][marker][method] is not None
               for marker in ("X", "Z") for method in METHODS)


def accepted(value, threshold):
    return value is not None and threshold is not None and value < threshold - TOL


def summarized(rows, thresholds):
    reports = {}
    groups = sorted({(row["target"], row["decoy"], row["mode"]) for row in rows})
    for target, decoy, mode in groups:
        selected = [r for r in rows if (r["target"], r["decoy"], r["mode"]) == (target, decoy, mode)]
        results = {}
        for method in METHODS:
            scores = [(r["scores"]["X"][method], r["scores"]["Z"][method]) for r in selected]
            paired = [(x, z) for x, z in scores if x is not None and z is not None]
            threshold = thresholds[method]
            results[method] = {
                "supported_seeds": len(paired),
                "genuine_wins": sum(x < z - TOL for x, z in paired),
                "decoy_wins": sum(z < x - TOL for x, z in paired),
                "ties": sum(abs(x - z) <= TOL for x, z in paired),
                "genuine_accepted": sum(accepted(x, threshold) for x, _ in paired),
                "decoy_accepted": sum(accepted(z, threshold) for _, z in paired),
            }
        reports["/".join((target, decoy, mode))] = {
            "support_range_by_seed": [min(r["pairs"] for r in selected), max(r["pairs"] for r in selected)],
            "common_supported_seeds": sum(common(r) for r in selected),
            "methods": results,
        }
    return reports


def negative_controls(words, thresholds):
    context = prior.Context(" ".join(w.form for w in words))
    rows = []
    for target in ("us", "in", "er"):
        for letter in "qtrn":
            if letter in target:
                continue
            values = context.scores(letter, *target)
            rows.append({
                "target": target, "standalone_letter": letter,
                "scores": values,
                "acceptances": {method: accepted(value, thresholds[method]) for method, value in values.items()},
            })
    return rows


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("phase", choices=["calibrate", "evaluate"])
    args = parser.parse_args()
    split = "dev" if args.phase == "calibrate" else "test"
    words, info = read_words(split)
    base = {"plan_sha256": sha(PLAN_PATH), "runner_sha256": sha(Path(__file__)),
            "parser_sha256": sha(ROOT / "latin_corpus.py"),
            "prior_context_sha256": sha(ROOT / "prior-position_context.py"),
            "source": info}
    if args.phase == "calibrate":
        all_rows = run_rows(words, PLAN["calibration_pairs"], ("all",), set())
        valid = [r for r in all_rows if common(r)]
        thresholds = {}
        for method in METHODS:
            decoys = sorted(r["scores"]["Z"][method] for r in valid)
            thresholds[method] = decoys[math.floor(.05 * len(decoys))] if decoys else None
        base.update({"thresholds": thresholds, "calibration_common_rows": len(valid),
                     "summary": summarized(all_rows, thresholds), "rows": all_rows})
        result = ROOT / "calibration.json"
    else:
        frozen_path = ROOT / "calibration.json"
        frozen = json.loads(frozen_path.read_text())
        for key in ("plan_sha256", "runner_sha256", "parser_sha256", "prior_context_sha256"):
            assert base[key] == frozen[key]
        train, train_info = read_words("train")
        dev, dev_info = read_words("dev")
        doc_sets = [set(meta["documents"]) for meta in (train_info, dev_info, info)]
        assert not any(doc_sets[i] & doc_sets[j] for i, j in ((0, 1), (0, 2), (1, 2)))
        observed_lemmas = {x.lemma for x in train + dev if x.lemma}
        new_lemmas = {x.lemma for x in words if x.lemma} - observed_lemmas
        thresholds = frozen["thresholds"]
        normal = run_rows(words, PLAN["calibration_pairs"], ("all",), new_lemmas)
        focus = run_rows(words, [PLAN["focus_pair"]], AMBIENT, new_lemmas)
        base.update({"calibration_sha256": sha(frozen_path), "thresholds": thresholds,
                     "document_sets_disjoint": True, "train_source": train_info, "dev_source": dev_info,
                     "new_test_lemmas": len(new_lemmas), "summary": summarized(normal + focus, thresholds),
                     "rows": normal + focus, "negative_controls": negative_controls(words, thresholds)})
        result = ROOT / "evaluation.json"
    result.write_text(json.dumps(base, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"result": result.name, "thresholds": thresholds, "summary": base["summary"]}, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.prior-position_context.py:
"""Frozen public reference-text test of role-correct word-position contexts."""
import argparse
import hashlib
import json
import math
import random
from collections import Counter, defaultdict
from pathlib import Path

from vs import refcorpus

ROOT = Path(__file__).resolve().parent
PLAN_BYTES = (ROOT/'plan.json').read_bytes()
PLAN = json.loads(PLAN_BYTES)
METHODS = ('unconditioned', 'position_all', 'position_info')
TOL = 1e-12


def save(name, value):
    (ROOT/name).write_bytes((json.dumps(value, indent=2)+'\n').encode())


def sha(data):
    return hashlib.sha256(data).hexdigest()


def js(p, q):
    np, nq = sum(p.values()), sum(q.values())
    assert np and nq
    total = 0.0
    for s in sorted(p.keys() | q.keys()):
        x, y = p[s]/np, q[s]/nq
        middle = (x+y)/2
        if x:
            total += x*math.log2(x/middle)/2
        if y:
            total += y*math.log2(y/middle)/2
    return total


def cell():
    return {'n': 0, 'left': Counter(), 'right': Counter()}


class Context:
    def __init__(self, text):
        self.positions = defaultdict(lambda: defaultdict(cell))
        self.all = defaultdict(cell)
        for word in text.split():
            for i, c in enumerate(word):
                key = (i == 0, i == len(word)-1)
                before = word[i-1] if i else ' '
                after = word[i+1] if i+1 < len(word) else ' '
                for record in (self.positions[c][key], self.all[c]):
                    record['n'] += 1
                    record['left'][before] += 1
                    record['right'][after] += 1

    def scores(self, c, a, b):
        out = dict.fromkeys(METHODS)
        if any(self.all[s]['n'] < 40 for s in (c, a, b)):
            return out
        out['unconditioned'] = (js(self.all[c]['left'], self.all[a]['left'])+
                                js(self.all[c]['right'], self.all[b]['right']))/2
        for method in ('position_all', 'position_info'):
            numerator = 0.0
            denominator = informative_occurrences = 0
            supported = True
            for (initial, final), record in self.positions[c].items():
                directions = []
                if method == 'position_all' or not initial:
                    directions.append(('left', self.positions[a][initial, False]))
                if method == 'position_all' or not final:
                    directions.append(('right', self.positions[b][False, final]))
                if directions:
                    informative_occurrences += record['n']
                for direction, reference in directions:
                    if reference['n'] < 20:
                        supported = False
                        break
                    numerator += record['n']*js(record[direction], reference[direction])
                    denominator += record['n']
                if not supported:
                    break
            if supported and denominator and (method != 'position_info' or informative_occurrences >= 40):
                out[method] = numerator/denominator
        return out


def source(language, partition):
    loader, offset = {
        'calibration': (refcorpus.calib_text, 40000),
        'evaluation': (refcorpus.control_text, 80000),
        'training': (refcorpus.train_text, 40000),
        'old_evaluation': (refcorpus.control_text, 40000),
    }[partition]
    text = ' '.join(loader(language))[offset:].split(' ', 1)[1]
    return ' '+text[:40000].rsplit(' ', 1)[0]+' '


def pool(text, target, decoy, mode, seed):
    groups = defaultdict(lambda: ([], []))
    offset = 0
    for word in text.split(' '):
        for i in range(len(word)-1):
            pair = word[i:i+2]
            if pair not in (target, decoy):
                continue
            start = offset+i
            key = (i == 0, i+2 == len(word))
            if mode in ('left', 'both'):
                key += (text[start-1],)
            if mode == 'both':
                key += (text[start+2],)
            groups[key][pair == decoy].append(start)
        offset += len(word)+1
    rng = random.Random(seed)
    blocked, pairs = set(), []
    for key, (true, wrong) in sorted(groups.items()):
        rng.shuffle(true)
        rng.shuffle(wrong)
        for i, j in zip(true, wrong):
            if abs(i-j) < 3 or i in blocked or j in blocked:
                continue
            pairs.append((i, j))
            blocked.update(range(i-2, i+3))
            blocked.update(range(j-2, j+3))
    rng.shuffle(pairs)
    return pairs


def plant(text, pairs):
    edits = sorted([(i, 'X') for i, j in pairs]+[(j, 'Z') for i, j in pairs])
    pieces, previous = [], 0
    for i, c in edits:
        pieces += [text[previous:i], c]
        previous = i+2
    pieces.append(text[previous:])
    return ''.join(pieces)


def trial(text, language, target, decoy, mode, fraction, seed, partition):
    matched = pool(text, target, decoy, mode, seed)
    pairs = matched[:len(matched)//2] if fraction == .5 else matched
    calc = Context(plant(text, pairs))
    assert calc.all['X']['n'] == calc.all['Z']['n'] == len(pairs)
    for i, j in pairs:
        assert text[i:i+2] == target and text[j:j+2] == decoy
        assert (text[i-1] == ' ', text[i+2] == ' ') == (text[j-1] == ' ', text[j+2] == ' ')
        if mode in ('left', 'both'):
            assert text[i-1] == text[j-1]
        if mode == 'both':
            assert text[i+2] == text[j+2]
    x, z = calc.scores('X', *target), calc.scores('Z', *target)
    if mode == 'both':
        for m in METHODS:
            assert (x[m] is None) == (z[m] is None)
            assert x[m] is None or abs(x[m]-z[m]) <= TOL
    return {'language': language, 'partition': partition, 'target': target, 'decoy': decoy,
            'mode': mode, 'fraction': fraction, 'seed': seed, 'pairs': len(pairs),
            'scores': {'X': x, 'Z': z},
            'common_eligible': all(x[m] is not None and z[m] is not None for m in METHODS),
            'candidate_position_counts': {str(key): record['n'] for key, record in calc.positions['X'].items()}}


def paired(partition):
    rows, sources = [], []
    for language, contrasts in PLAN['primary_contrasts'].items():
        text = source(language, partition)
        sources.append({'language': language, 'characters': len(text), 'sha256': sha(text.encode())})
        for target, decoy in contrasts:
            for mode in PLAN['matching_modes']:
                for fraction in PLAN['fractions']:
                    for seed in PLAN['seeds']:
                        rows.append(trial(text, language, target, decoy, mode, fraction, seed, partition))
    return rows, sources


def primary(rows):
    return [r for r in rows if r['mode'] == 'left' and r['fraction'] == 1 and r['common_eligible']]


def accept(score, threshold):
    return score is not None and threshold is not None and score < threshold-TOL


def summarize(rows, thresholds):
    out = []
    for mode in PLAN['matching_modes']:
        for fraction in PLAN['fractions']:
            selected = [r for r in rows if r['mode'] == mode and r['fraction'] == fraction]
            common = [r for r in selected if r['common_eligible']]
            methods = {}
            for m in METHODS:
                count = Counter({'genuine_win': 0, 'decoy_win': 0, 'tie': 0, 'accepted_X': 0, 'accepted_Z': 0})
                for r in common:
                    x, z = r['scores']['X'][m], r['scores']['Z'][m]
                    count['genuine_win' if x < z-TOL else 'decoy_win' if z < x-TOL else 'tie'] += 1
                    count['accepted_X'] += accept(x, thresholds[m])
                    count['accepted_Z'] += accept(z, thresholds[m])
                methods[m] = dict(count)
            out.append({'mode': mode, 'fraction': fraction, 'attempted': len(selected),
                        'common_eligible': len(common),
                        'supported_by_method': {m: sum(all(r['scores'][c][m] is not None for c in ('X', 'Z')) for r in selected) for m in METHODS},
                        'methods': methods})
    return out


def negatives(thresholds):
    rows = []
    for language, contrasts in PLAN['primary_contrasts'].items():
        evaluation = source(language, 'evaluation')
        streams = [('natural', None, evaluation)]
        train = source(language, 'training').strip()
        outgoing = defaultdict(Counter)
        for a, b in zip(train, train[1:]):
            outgoing[a][b] += 1
        starts = Counter(w[0] for w in train.split())
        def draw(rng, counts):
            point = rng.randrange(sum(counts.values()))
            for c, n in sorted(counts.items()):
                if point < n:
                    return c
                point -= n
            raise AssertionError('draw')
        for seed in PLAN['chain_seeds']:
            rng = random.Random(seed)
            letters = [draw(rng, starts)]
            while len(letters) < len(evaluation)-2:
                choices = outgoing[letters[-1]]
                if len(letters) == len(evaluation)-3:
                    choices = Counter({s: n for s, n in choices.items() if s != ' '})
                letters.append(draw(rng, choices or starts))
            streams.append(('direct_chain', seed, ' '+''.join(letters)+' '))
        for origin, seed, text in streams:
            calc = Context(text)
            for target, _ in contrasts:
                candidates = []
                for c in sorted(calc.all):
                    if c in target or not c.islower() or calc.all[c]['n'] < 40:
                        continue
                    values = calc.scores(c, *target)
                    candidates.append({'candidate': c, 'scores': values,
                                       'accepted': {m: accept(values[m], thresholds[m]) for m in METHODS}})
                rows.append({'language': language, 'origin': origin, 'seed': seed, 'target': target,
                             'characters': len(text), 'sha256': sha(text.encode()), 'candidates': candidates})
    return rows


def diagnostic(thresholds):
    rows = []
    for partition, seeds in [('old_evaluation', [58471, 58477, 58481, 58487, 58493]),
                             ('evaluation', PLAN['seeds'])]:
        text = source('latin', partition)
        for seed in seeds:
            row = trial(text, 'latin', 'us', 'um', 'left', 1, seed, partition)
            row['source_sha256'] = sha(text.encode())
            row['accepted'] = {c: {m: accept(row['scores'][c][m], thresholds[m]) for m in METHODS} for c in ('X', 'Z')}
            rows.append(row)
    text = ' '.join(['x ab aba bab']*100)
    scores = Context(text).scores('x', 'a', 'b')
    assert scores['position_all'] == 0 and scores['position_info'] is None
    return {'us_um': rows, 'boundary_trap': {'text_recipe': 'x ab aba bab repeated 100 times', 'scores': scores,
            'accepted': {m: accept(scores[m], thresholds[m]) for m in METHODS}}}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=('calibrate', 'evaluate'))
    phase = parser.parse_args().phase
    if phase == 'calibrate':
        rows, sources = paired('calibration')
        supported = primary(rows)
        thresholds = {}
        for m in METHODS:
            scores = sorted(r['scores']['Z'][m] for r in supported)
            thresholds[m] = scores[math.floor(.05*len(scores))] if scores else None
        output = {'plan_sha256': sha(PLAN_BYTES), 'script_sha256': sha(Path(__file__).read_bytes()),
                  'thresholds': thresholds, 'calibration_negative_count': len(supported), 'sources': sources,
                  'summary': summarize(rows, thresholds), 'paired_rows': rows}
        name = 'calibration.json'
    else:
        frozen = (ROOT/'calibration.json').read_bytes()
        calibration = json.loads(frozen)
        assert calibration['plan_sha256'] == sha(PLAN_BYTES)
        assert calibration['script_sha256'] == sha(Path(__file__).read_bytes())
        thresholds = calibration['thresholds']
        rows, sources = paired('evaluation')
        output = {'plan_sha256': sha(PLAN_BYTES), 'calibration_sha256': sha(frozen), 'thresholds': thresholds,
                  'sources': sources, 'summary': summarize(rows, thresholds), 'paired_rows': rows,
                  'negative_controls': negatives(thresholds), 'diagnostics': diagnostic(thresholds)}
        name = 'evaluation.json'
    save(name, output)
    print(json.dumps({'phase': phase, 'primary_common': len(primary(rows)), 'thresholds': thresholds,
                      'summary': output['summary']}, indent=2))


if __name__ == '__main__':
    main()

scripts_as_text.verify_prior_experiment.py:
"""Check prior PR 623 replay against the published structured outputs."""
import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent / "prior-reproduction"
TOLERANCE = 1e-12


def load(path):
    return json.loads(path.read_bytes())


def compare(expected, actual):
    floating = []
    structural = []

    def walk(a, b, key):
        if isinstance(a, dict) and isinstance(b, dict) and a.keys() == b.keys():
            for field in a:
                walk(a[field], b[field], key + [field])
        elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
            for index, pair in enumerate(zip(a, b, strict=True)):
                walk(*pair, key + [str(index)])
        elif a != b:
            if isinstance(a, float) and isinstance(b, float):
                floating.append(abs(a - b))
            else:
                structural.append("/".join(key))

    walk(expected, actual, [])
    return {
        "floating_point_differences": len(floating),
        "maximum_absolute_floating_point_difference": max(floating, default=0.0),
        "other_differences": structural,
        "equal_within_existing_score_tolerance": not structural and max(floating, default=0.0) <= TOLERANCE,
    }


def summarize_negative(rows):
    results = []
    for row in rows:
        candidates = row["candidates"]
        common = [c for c in candidates if all(v is not None for v in c["scores"].values())]
        result = {k: v for k, v in row.items() if k != "candidates"}
        result.update({"candidate_count": len(candidates), "common_supported": len(common), "methods": {}})
        for method in ("unconditioned", "position_all", "position_info"):
            supported = [c["scores"][method] for c in candidates if c["scores"][method] is not None]
            result["methods"][method] = {
                "accepted_candidates": [c["candidate"] for c in candidates if c["accepted"][method]],
                "common_accepted_candidates": [c["candidate"] for c in common if c["accepted"][method]],
                "minimum_loss": min(supported) if supported else None,
                "supported": len(supported),
            }
        results.append(result)
    return results


def main():
    previous = load(ROOT / "previous-spec.json")
    frozen = load(ROOT / "public/calibration-freeze.json")
    public_plan = load(ROOT / "public/preregistered.json")
    assert previous["plan_sha256"] == public_plan["plan_sha256"] == frozen["plan_sha256"]
    assert public_plan["reproduction"]["plan_json_bytes"] == frozen["reproduction"]["plan_json_bytes"]
    preregistered_cutoffs = frozen["calibration_frozen_before_evaluation"]
    assert preregistered_cutoffs["thresholds"] == previous["results"]["calibration"]["thresholds"]
    assert preregistered_cutoffs["sha256"] == previous["output_digests"]["calibration.json"]
    cal = load(ROOT / "run/calibration.json")
    ev = load(ROOT / "run/evaluation.json")
    verification = load(ROOT / "run/verification.json")
    expected_eval = {k: v for k, v in previous["results"]["evaluation"].items() if k != "calibration_sha256"}
    eval_overlap = {k: ev[k] for k in expected_eval}
    archived = {}
    for filename in ("calibration.json", "evaluation.json", "verification.json"):
        recorded = previous["output_digests"][filename]
        found = hashlib.sha256((ROOT / "run" / filename).read_bytes()).hexdigest()
        archived[filename] = {"expected": recorded, "observed": found, "byte_exact": recorded == found}
    tests = {
        "calibration": compare(previous["results"]["calibration"], cal),
        "evaluation_shared_public_fields_excluding_calibration_digest": compare(expected_eval, eval_overlap),
        "independent_verification": compare(previous["results"]["independent_verification"], verification),
        "negative_control_published_summaries": compare(
            previous["results"]["negative_control_sample_results"], summarize_negative(ev["negative_controls"]),
        ),
    }
    assert tests["calibration"]["equal_within_existing_score_tolerance"]
    assert tests["evaluation_shared_public_fields_excluding_calibration_digest"]["equal_within_existing_score_tolerance"]
    assert tests["independent_verification"]["equal_within_existing_score_tolerance"]
    assert tests["negative_control_published_summaries"]["equal_within_existing_score_tolerance"]
    assert verification["all_support_and_acceptance_decisions_match"]
    result = {
        "pr": "https://github.com/Ayan-Bandyopadhyay/voynich-swarm/pull/623",
        "runtime_base": previous["runtime_base"],
        "plan_commit": previous["preregistration_commit"],
        "calibration_freeze_commit": previous["calibration_freeze_commit"],
        "public_plan_sha_verified": previous["plan_sha256"],
        "public_freeze_contains_identical_plan": True,
        "formal_launcher_verification": "The bundled launcher verified the inputs and initial scripts and stopped at the calibration byte SHA mismatch. The original evaluation and verification scripts were then run without editing the published corpus, algorithms or thresholds.",
        "runtime_version": "Python 3.12.14 on Linux",
        "published_score_tolerance": TOLERANCE,
        "structured_comparisons": tests,
        "sha_checks": archived,
        "scope": "The archived evaluation contains additional negative-control details outside the compared summary. This distinguishes structured numerical reproduction and agreement of pairing, threshold and acceptance decisions from byte-for-byte identity.",
    }
    (ROOT / "reproduction-result.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

scripts_as_text.audit_morphology_support.py:
"""Count the charter, lexical and word-position support of frozen us/um matches.

Uses only the annotated test corpus and the frozen matching functions. Never
constructs a Context object, calculates a score, or changes a reported cutoff.
"""

from collections import Counter, defaultdict
from hashlib import sha256
import json
from pathlib import Path

from charter_context import Site, Word, make_pairs
from latin_corpus import iter_occurrences, iter_sentences


ROOT = Path(__file__).resolve().parent
FOCUS = ("us", "um")


def digest(path):
    return sha256(path.read_bytes()).hexdigest()


def _build_input(path):
    sentences = list(iter_sentences(path, split="test"))
    documents = {}
    words = {}
    ordinal = 0
    for sentence in sentences:
        for token in sentence.tokens:
            ordinal += 1
            morph = token.morphology
            lemma = morph.lemma_ascii or "" if morph is not None else ""
            fields = (
                morph.upos or "", morph.case or "", morph.number or "", morph.gender or ""
            ) if morph is not None else ("", "", "", "")
            for part, form in enumerate(token.ascii_parts):
                index = len(words)
                words[sentence.sent_id, token.id, part] = Word(
                    index, ordinal, form, lemma if " " not in lemma else "", *fields,
                )
                documents[index] = sentence.doc_id

    occurrences = list(iter_occurrences(sentences, FOCUS, include_fragments=True))
    sites = [
        (o.pair == FOCUS[1], Site(words[o.sent_id, o.token_id, o.part_index], o.start, o.left, o.right))
        for o in occurrences
    ]
    return occurrences, sites, documents


def _internal_support(occurrences):
    strata = defaultdict(Counter)
    for o in occurrences:
        if o.role in ("initial", "interior"):
            strata[o.role, o.left][o.pair] += 1
    by_role = {}
    for role in ("initial", "interior"):
        groups = {left: count for (kind, left), count in strata.items() if kind == role}
        raw = {pair: sum(count[pair] for count in groups.values()) for pair in FOCUS}
        by_role[role] = {
            "source_occurrences": raw,
            "upper_bound_matching_only_role": min(raw.values()),
            "upper_bound_matching_role_and_immediate_left": sum(min(c[p] for p in FOCUS) for c in groups.values()),
            "nonempty_exact_left_strata": sum(all(c[p] for p in FOCUS) for c in groups.values()),
            "left_strata_with_both": [
                {"left": left, "source_occurrences": {p: count[p] for p in FOCUS},
                 "pair_upper_bound": min(count[p] for p in FOCUS)}
                for left, count in sorted(groups.items()) if all(count[p] for p in FOCUS)
            ],
        }
    return {
        "source_occurrences": {pair: sum(row["source_occurrences"][pair] for row in by_role.values()) for pair in FOCUS},
        "upper_bound_matching_role_and_immediate_left": sum(row["upper_bound_matching_role_and_immediate_left"] for row in by_role.values()),
        "by_role": by_role,
    }


def _terminal_summary(pairs, documents):
    groups = Counter()
    docs_by_group = defaultdict(set)
    sides = [Counter(), Counter()]
    for a, b in pairs:
        key = (a.word.lemma, a.word.form[:-2], a.word.upos)
        assert key == (b.word.lemma, b.word.form[:-2], b.word.upos)
        groups[key] += 1
        for i, site in enumerate((a, b)):
            doc = documents[site.word.index]
            assert doc is not None
            sides[i][doc] += 1
            docs_by_group[key].add(doc)
    docs = sides[0] + sides[1]
    rows = [{"lemma": lemma, "stem": stem, "upos": upos, "matched_pairs": n,
             "share_of_pairs": n / len(pairs), "contributing_charters": len(docs_by_group[lemma, stem, upos])}
            for (lemma, stem, upos), n in sorted(groups.items(), key=lambda row: (-row[1], row[0]))]
    return {
        "matched_pairs": len(pairs), "matched_occurrence_slots": 2 * len(pairs),
        "charters_either_side": len(docs),
        "charters_us_side": len(sides[0]), "charters_um_side": len(sides[1]),
        "charters_both_sides": len(sides[0].keys() & sides[1].keys()),
        "same_charter_matched_pairs": sum(documents[a.word.index] == documents[b.word.index] for a, b in pairs),
        "lemma_stem_upos_groups": len(groups), "groups": rows,
        "largest_charter_matched_slots": max(docs.values()),
        "largest_charters": [doc for doc in sorted(docs) if docs[doc] == max(docs.values())],
    }


def main():
    corpus = ROOT / "corpus" / "test.conllu"
    frozen = ROOT / "evaluation.json"
    evaluation = json.loads(frozen.read_text(encoding="utf-8"))
    assert evaluation["source"]["sha256"] == digest(corpus)
    assert evaluation["parser_sha256"] == digest(ROOT / "latin_corpus.py")
    assert evaluation["runner_sha256"] == digest(ROOT / "charter_context.py")
    occurrences, sites, documents = _build_input(corpus)
    by_mode = {mode: {r["seed"]: r for r in evaluation["rows"] if (r["target"], r["decoy"]) == FOCUS and r["mode"] == mode}
               for mode in ("internal", "terminal_same_stem_case")}
    internal = _internal_support(occurrences)
    terminal = []
    union_slots = set()
    union_docs = set()
    for seed, row in sorted(by_mode["terminal_same_stem_case"].items()):
        pairs, support = make_pairs(sites, "terminal_same_stem_case", seed, frozenset())
        assert len(pairs) == row["pairs"] and support == row["support"]
        terminal.append({"seed": seed, **_terminal_summary(pairs, documents)})
        union_slots.update((site.word.index, site.onset) for pair in pairs for site in pair)
        union_docs.update(documents[site.word.index] for pair in pairs for site in pair)
    for row in by_mode["internal"].values():
        assert row["support"]["source_sites"] == [internal["source_occurrences"][p] for p in FOCUS]
        assert row["support"]["stratum_unrestricted_upper_bound"] == internal["upper_bound_matching_role_and_immediate_left"]
        assert row["position_counts"]["word_initial"] == internal["by_role"]["initial"]["upper_bound_matching_role_and_immediate_left"]
    report = {
        "scope": "UD Latin LLCT test charters only. Support and concentration from the same frozen match, with no new scores. Counts per matched seed reuse source charters and are not independent observations.",
        "evaluation_sha256": digest(frozen), "test_sha256": digest(corpus),
        "internal_us_um": internal,
        "terminal_same_stem_case": {
            "unique_occurrence_slots_across_seeds": len(union_slots),
            "unique_charters_across_seeds": len(union_docs),
            "seeds": terminal,
        },
    }
    (ROOT / "morphology_support.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(internal)
    for row in terminal:
        print(row["seed"], row["charters_either_side"], row["charters_us_side"], row["charters_um_side"],
              row["lemma_stem_upos_groups"], row["groups"][0])
    print("unique across seeds", len(union_slots), "slots and", len(union_docs), "charters")


if __name__ == "__main__":
    main()
